-- Refresh only exact legacy Hotori seed text. Independently edited sections are preserved.
-- Public source audit: 2026-10-21; Kaiden October 2026, Wotpack 2026-08-24, Prydwen 2026-07-02.

UPDATE guide_sections SET content_markdown = 'Хотори наносит основной урон в остановке времени. Её навык тратит 60 единиц «Незакрытых часов» и открывает 5 секунд для записи навыков поддержки и перенаправления союзников — до трёх разных персонажей. Сверхспособность доступна при 120 единицах: она воспроизводит запись и удерживает Хотори на поле до окончания остановки времени.', updated_at = CURRENT_TIMESTAMP WHERE id = 'hotori-guide-tldr-0012' AND content_markdown = 'Хотори — S-ранговый ДД атрибута Космос с упором на сверхспособность. Перед главным окном урона выполните три навыка перенаправления или поддержки, затем активируйте сверхспособность. Базовые атаки помогают поддерживать цикл, а обычный навык имеет меньший приоритет.';

UPDATE guide_sections SET content_markdown = 'Хотори полезна для команд Цветения и коротких окон урона. Между её выходами на поле работают союзники; внутри остановки времени продолжают атаковать бутоны. Учитывайте требовательное окно записи и невозможность переключиться во время сверхспособности. Решение о призыве зависит от уже собранной команды и доступной экипировки.', updated_at = CURRENT_TIMESTAMP WHERE id = 'hotori-guide-upgrade-0012' AND content_markdown = 'Хотори подходит аккаунту, которому нужен основной ДД атрибута Космос. Особенно хорошо она раскрывается рядом с персонажами, усиливающими её короткое окно урона. Если основная группа ДД уже собрана, перед призывом сравните потребность в новом керри с другими приоритетами аккаунта.';

UPDATE guide_sections SET content_markdown = '## Дуга

Marching Beyond Time — сигнатурный вариант; Fluff of Fearlessness — альтернатива. Не сравнивайте варианты без учёта уровня наложения и условий команды.

## Консоль и картриджи

Lost Radiance («Утраченное сияние»): 2 части дают 10% урона Космоса, 4 части — 25% игнорирования защиты на 20 секунд после сверхспособности. Бонус консоли Хотори зависит от модулей типа III.

## Характеристики

Балансируйте шанс и урон критического попадания, бонус Космоса и атаку. При смене дуги меняется потребность в критическом шансе; универсального порога для всех сборок нет. Рекомендации рассчитаны на боевую роль и требуют сверки с выбранной дугой и пробуждениями.', updated_at = CURRENT_TIMESTAMP WHERE id = 'hotori-guide-builds-0012' AND content_markdown = '## Лучшие дуги

- **Марш сквозь время** — основной выбор для ротации с тремя действиями перенаправления или поддержки перед сверхспособностью.
- **Пушок бесстрашия** — S-ранговая альтернатива с усилением атаки и шанса критического попадания после сверхспособности.
- **Забытое** — доступный A-ранговый вариант, пока S-ранговые дуги недоступны; условие усиления связано с запасом HP выше 50 %.

Точные модули и приоритеты характеристик пока не подтверждены несколькими русскоязычными источниками и должны быть проверены редактором перед добавлением.';

UPDATE guide_sections SET content_markdown = '## Цветение

**Хотори · Наналли · Цзююань · Зеро** — вариант из русскоязычного гайда Wotpack.

**Хотори · Зеро · Цзююань · Сакири** — рекомендуемый состав Kaiden.

Выбирайте вариант под доступных персонажей. Эти источники предлагают разные составы; их не следует выдавать за единственную обязательную команду. Порядок навыков и состав можно уточнить в карточках отрядов ниже.', updated_at = CURRENT_TIMESTAMP WHERE id = 'hotori-guide-teams-0012' AND content_markdown = '## Премиум-состав

**Наналли · Хотори · Адлер · Эдгар**

Наналли поддерживает атрибут Космос, Адлер помогает снижать защиту цели и защищает отряд, Эдгар отвечает за лечение, а Хотори закрывает подготовленное окно сверхспособностью.

## Более доступный состав

**Хотори · Фадия · Ханиэль · Эдгар**

Фадия принимает и перенаправляет урон, Ханиэль усиливает команду, Эдгар лечит. Состав проще собрать без полного набора S-ранговых партнёров.';

UPDATE guide_sections SET content_markdown = '1. Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.
2. Примените навык Хотори, открывающий окно записи.
3. В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.
4. Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.
5. Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.
6. После завершения окна вернитесь к действиям союзников и подготовке следующей записи.', updated_at = CURRENT_TIMESTAMP WHERE id = 'hotori-guide-rotations-0012' AND content_markdown = '1. Начните бой базовыми атаками и накопите цикл эспера.
2. Примените навык поддержки Хотори.
3. Переключитесь на союзников и активируйте командные усиления.
4. Вернитесь к Хотори и выполните ещё два действия перенаправления или поддержки — всего их должно быть три.
5. Сразу активируйте сверхспособность.
6. Продолжите базовыми атаками в оставшемся окне урона и начните подготовку следующего цикла.';

UPDATE guide_sections SET content_markdown = '- Не путайте три записываемых действия разных союзников с зарядами сигнатурной дуги.
- Сначала откройте окно записи навыком Хотори: действия до него не записываются.
- Повторное применение навыка заменяет предыдущую запись.
- Проверяйте готовность сверхспособности по шкале ресурса; базовые атаки не ускоряют её заполнение.
- Выбирайте пробуждения под задачу и бюджет, сверяя их эффекты в профиле. Не переносите расчёты для A6 и усиленной дуги на персонажа без вложений.', updated_at = CURRENT_TIMESTAMP WHERE id = 'hotori-guide-mistakes-0012' AND content_markdown = '- Не активируйте сверхспособность до трёх действий перенаправления или поддержки: так теряется ключевая часть усиления.
- Не оставляйте командные усиления на время после главного удара Хотори — они должны быть подготовлены заранее.
- Обычный навык имеет меньший приоритет, чем сверхспособность и навык поддержки; не задерживайте им основное окно урона.';

