UPDATE teams SET status = 'archived', updated_at = CURRENT_TIMESTAMP WHERE id = 'team-hotori-accessible' AND guide_id = 'guide-hotori' AND status = 'published' AND title = 'Более доступный состав' AND budget = 'Mixed' AND difficulty = '' AND power = 0 AND good_at = '' AND weak_at = '' AND synergy = 'Фадия принимает и перенаправляет урон, Ханиэль усиливает команду, Эдгар лечит. Состав проще собрать без полного набора S-ранговых партнёров.' AND rotation = '' AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-hotori-accessible' AND character_id = 'hotori' AND role = 'Основной ДД' AND position = 1) AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-hotori-accessible' AND character_id = 'fadia' AND role = 'Контроль' AND position = 2) AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-hotori-accessible' AND character_id = 'haniel' AND role = 'Усиление' AND position = 3) AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-hotori-accessible' AND character_id = 'edgar' AND role = 'Лечение' AND position = 4) AND (SELECT group_concat(character_id, ',') FROM (SELECT character_id FROM team_members WHERE team_id = 'team-hotori-accessible' ORDER BY character_id)) = 'edgar,fadia,haniel,hotori';

UPDATE teams SET status = 'archived', updated_at = CURRENT_TIMESTAMP WHERE id = 'team-chaos-eclipse' AND guide_id = 'guide-hotori' AND status = 'published' AND title = 'Премиум-состав' AND budget = 'Mixed' AND difficulty = '' AND power = 0 AND good_at = '' AND weak_at = '' AND synergy = 'Наналли поддерживает атрибут Космос, Адлер помогает снижать защиту цели и защищает отряд, Эдгар отвечает за лечение, а Хотори закрывает подготовленное окно сверхспособностью.' AND rotation = 'Начните бой базовыми атаками и накопите цикл эспера.\nПримените навык поддержки Хотори.\nПереключитесь на союзников и активируйте командные усиления.\nВернитесь к Хотори и выполните ещё два действия перенаправления или поддержки.\nСразу активируйте сверхспособность.\nПродолжите базовыми атаками и начните подготовку следующего цикла.' AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-chaos-eclipse' AND character_id = 'nanally' AND role = 'Поддержка' AND position = 1) AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-chaos-eclipse' AND character_id = 'hotori' AND role = 'Основной ДД' AND position = 2) AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-chaos-eclipse' AND character_id = 'adler' AND role = 'Защита и ослабление' AND position = 3) AND EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-chaos-eclipse' AND character_id = 'edgar' AND role = 'Лечение' AND position = 4) AND (SELECT group_concat(character_id, ',') FROM (SELECT character_id FROM team_members WHERE team_id = 'team-chaos-eclipse' ORDER BY character_id)) = 'adler,edgar,hotori,nanally';

INSERT OR IGNORE INTO teams (id, slug, guide_id, title, team_type, budget, difficulty, power, good_at, weak_at, synergy, rotation, rotation_steps_json, status) SELECT 'team-hotori-blossom-0029', 'team-hotori-blossom-0029', 'guide-hotori', 'Цветение с Наналли', 'Цветение', 'Mixed', 'Окно записи 5 секунд', 0, '', '', 'Наналли и Цзююань формируют основу Цветения, Зеро помогает поддерживать цикл. Хотори записывает действия союзников и воспроизводит их в остановке времени. Вариант Wotpack; уточняйте порядок навыков под доступные пробуждения.', 'Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.
Примените навык Хотори, открывающий окно записи.
В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.
Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.
Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.
После завершения окна вернитесь к действиям союзников и подготовке следующей записи.', '["Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.","Примените навык Хотори, открывающий окно записи.","В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.","Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.","Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.","После завершения окна вернитесь к действиям союзников и подготовке следующей записи."]', 'published' WHERE EXISTS (SELECT 1 FROM guides WHERE id = 'guide-hotori') AND (SELECT COUNT(*) FROM characters WHERE id IN ('hotori', 'nanally', 'jiuyuan', 'esper-zero')) = 4;
INSERT OR IGNORE INTO team_members (team_id, character_id, role, position) SELECT * FROM (SELECT 'team-hotori-blossom-0029', 'hotori', 'Урон в остановке времени', 1
UNION ALL SELECT 'team-hotori-blossom-0029', 'nanally', 'Подготовка окна урона', 2
UNION ALL SELECT 'team-hotori-blossom-0029', 'jiuyuan', 'Подготовка окна урона', 3
UNION ALL SELECT 'team-hotori-blossom-0029', 'esper-zero', 'Подготовка окна урона', 4) WHERE EXISTS (SELECT 1 FROM teams WHERE id = 'team-hotori-blossom-0029') AND NOT EXISTS (SELECT 1 FROM team_members WHERE team_id = 'team-hotori-blossom-0029');

